(3375601, 467149, 73230, '<td valign="top">Colourful, sharp, does the job, Well done</td>', 'Colourful, sharp, does the job, Well done', '2007-02-17 15:07:37.000000', NULL, 1),
(3375604, 467367, 73230, '<td valign="top">Beautiful. simply beautiful. Well done !</td>', 'Beautiful. simply beautiful. Well done !', '2007-02-17 15:08:22.000000', NULL, 1),
